import os
import csv

# Define the paths to the output files
output_files = {
    "t01_selected_indicators": "outputs/t01_selected_indicators.csv",
    "t05_clean_stops": "outputs/t05_clean_stops.csv",
    "t08_pois_clean": "outputs/t08_pois_clean.csv",
    "t10_accessibility_scores": "outputs/t10_accessibility_scores.csv",
    "t13_city_clusters": "outputs/t13_city_clusters.csv",
}

# Define the validation checks
def validate_files():
    validation_results = []

    # Check if each file exists
    for name, path in output_files.items():
        if not os.path.exists(path):
            validation_results.append({
                "check_name": f"file_exists_{name}",
                "passed": False,
                "message": f"File {path} does not exist."
            })
            continue

        # Check if the file is not empty
        if os.path.getsize(path) == 0:
            validation_results.append({
                "check_name": f"file_not_empty_{name}",
                "passed": False,
                "message": f"File {path} is empty."
            })
            continue

        # Check if the file has the correct headers (example for CSV files)
        with open(path, 'r') as file:
            reader = csv.reader(file)
            headers = next(reader, None)

            if headers:
                validation_results.append({
                    "check_name": f"has_headers_{name}",
                    "passed": True,
                    "message": f"File {path} has headers: {headers}."
                })
            else:
                validation_results.append({
                    "check_name": f"has_headers_{name}",
                    "passed": False,
                    "message": f"File {path} does not have headers."
                })

    # Additional checks can be added here

    return validation_results

# Run the validation checks
validation_results = validate_files()

# Write the validation results to the output JSON file
with open("outputs/t14_validation_summary.json", "w") as json_file:
    json.dump(validation_results, json_file, indent=4)
"}

